// The condition keys that take a value. They return a plain string, so wrap
// them in policy.Key when a condition wants a policy.ConditionKey.
func ConditionKeyAttributeFor(value string) string { return "ec2:Attribute/" + value }

func ConditionKeyResourceTagFor(value string) string { return "ec2:ResourceTag/" + value }
